cypress_script:
describe('Multi-Level Navigation Menu', () => {
  it('should navigate to Sub Sub Item 1', () => {
    cy.visit('https://demoqa.com/menu');
    cy.contains('Main Item 1').click();
    cy.contains('Sub Sub Item 1').click();
    cy.url().should('include', '/menu');
  });

  it('should not navigate on Main Item 1 click', () => {
    cy.visit('https://demoqa.com/menu');
    cy.contains('Main Item 1').click();
    cy.url().should('eq', 'https://demoqa.com/menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-Level Navigation Menu', () => {
  test('should navigate to Sub Sub Item 1', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('text=Main Item 1');
    await page.click('text=Sub Sub Item 1');
    expect(page.url()).toContain('/menu');
  });

  test('should not navigate on Main Item 1 click', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('text=Main Item 1');
    expect(page.url()).toBe('https://demoqa.com/menu');
  });
});
